 @page "/notifications"
 @rendermode InteractiveServer
 @using BlazorApp.Services
 @inject NotificationService NotificationService
 @implements IDisposable

 <PageTitle>Notifications</PageTitle>

 <h1>
     Notifications
     @if (Items is not null)
     {
         <span class="badge bg-primary ms-2">@Items.Count</span>
     }
 </h1>

 @if (Items is null)
 {
     <p><em>Loading notifications...</em></p>
 }
 else if (Items.Count == 0)
 {
     <p>No notifications yet.</p>
 }
 else
 {
     <ul class="list-group">
         @foreach (var notification in Items.OrderByDescending(n => n.Timestamp))
         {
             <li class="list-group-item">
                 <strong>@notification.Message</strong>
                 <small class="text-muted ms-2">@notification.Timestamp.ToString("HH:mm:ss")</small>
             </li>
         }
     </ul>
 }

 @code {
     private CancellationTokenSource? _cts;
     private DateTime _lastCheck;

     [PersistentState]
     public List<Notification>? Items { get; set; }

     protected override async Task OnInitializedAsync()
     {
         // Only fetch if not restored from prerendered state
         Items ??= await NotificationService.GetNotificationsAsync();
         _lastCheck = Items.Count > 0
             ? Items.Max(n => n.Timestamp)
             : DateTime.UtcNow;
     }

     protected override void OnAfterRender(bool firstRender)
     {
         if (firstRender)
         {
             // Start polling only after the page is interactive (not during prerender)
             _cts = new CancellationTokenSource();
             _ = PollForNotificationsAsync(_cts.Token);
         }
     }

     private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
     {
         while (!cancellationToken.IsCancellationRequested)
         {
             await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

             var newItems = await NotificationService.GetNotificationsSinceAsync(_lastCheck);
             if (newItems.Count > 0)
             {
                 Items!.AddRange(newItems);
                 _lastCheck = newItems.Max(n => n.Timestamp);
                 await InvokeAsync(StateHasChanged);
             }
         }
     }

     public void Dispose()
     {
         _cts?.Cancel();
         _cts?.Dispose();
     }
 }

